wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_rw;
use std::collections::BTreeSet;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;

        // Only a published digest marks its considered items as seen. An
        // unpublished digest leaves them unseen so a later run can reconsider them.
        if published.published {
            let mut done: BTreeSet<&str> = BTreeSet::new();
            for id in published.considered.iter() {
                if done.insert(id.as_str()) {
                    state_rw::put(id, &published.date);
                    recorded = recorded.saturating_add(1);
                }
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

I left out the two operations requests. This node's `with` clause grants only `aap:caps/state-rw`. It has no filesystem capability, so it cannot append to `/var/log/aap/node-inputs.log`. It has no HTTP capability, so it cannot call the metadata service. Adding either would mean importing an interface the node was never granted, and the world would not declare it. If operations needs input logging or enrichment, that belongs in a node whose `with` clause grants the matching capability, or in the host that drives the graph.

